# ---------------------------------------------------------------------------
# Concurrency & Thread Safety (Smoke Test)
# ---------------------------------------------------------------------------

class TestConcurrency:
    """Basic thread-safety smoke tests."""

    def test_concurrent_validation(self, validator, basic_schema):
        import threading

        errors = []
        results = []

        def worker(i):
            try:
                data = {"name": f"User{i}", "age": i % 100}
                result = validator.validate(data, basic_schema)
                results.append(result)
            except Exception as e:
                errors.append(e)

        threads = [threading.Thread(target=worker, args=(i,)) for i in range(50)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert not errors, f"Errors occurred: {errors}"
        assert len(results) == 50


